const SCHEMA = "CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS cars (id INTEGER PRIMARY KEY AUTOINCREMENT, status TEXT NOT NULL CHECK(status IN ('draft','sale','archive')), revision INTEGER NOT NULL DEFAULT 0, document TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT);\nCREATE INDEX IF NOT EXISTS cars_status ON cars(status, published_at DESC, id DESC);\nCREATE TABLE IF NOT EXISTS definitions (id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT NOT NULL UNIQUE, document TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS photos (id INTEGER PRIMARY KEY AUTOINCREMENT, car_id INTEGER NOT NULL REFERENCES cars(id) ON DELETE CASCADE, position INTEGER NOT NULL, main INTEGER NOT NULL DEFAULT 0, filename TEXT NOT NULL, asset TEXT, data BLOB, metadata TEXT NOT NULL DEFAULT '{}');\nCREATE INDEX IF NOT EXISTS photos_car ON photos(car_id,position);\nCREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','manager')), active INTEGER NOT NULL DEFAULT 1, password TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);\nCREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);\nCREATE TABLE IF NOT EXISTS pdfs (car_id INTEGER PRIMARY KEY REFERENCES cars(id) ON DELETE CASCADE, data BLOB NOT NULL, generated_at TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS login_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);\n";
